3	namespace App\Http\Controllers\Api\Webhooks;
4	
5	use App\Http\Controllers\Api\ApiController;
6	use App\Jobs\Square\SyncSquareCatalogDeltaJob;
7	use App\Models\Core\Professional\Professional;
8	use App\Models\Core\Professional\ProfessionalIntegration;
9	use App\Services\Square\SquareServiceSyncService;
10	use Illuminate\Http\JsonResponse;
11	use Illuminate\Http\Request;
12	use Illuminate\Support\Facades\Cache;
13	use Illuminate\Support\Facades\Log;
14	
15	// V2: Square catalog webhook — validates HMAC, deduplicates events, triggers service sync. Booking integration only.
16	class SquareCatalogWebhookController extends ApiController
17	{
18	    public function __invoke(Request $request, SquareServiceSyncService $syncService): JsonResponse
19	    {
20	        if (! (bool) config('sidest.features.square_sync', false)) {
21	            Log::info('Square webhook suppressed — square_sync feature flag is off');
22	
23	            return $this->success(['received' => true, 'feature_gated' => true]);
24	        }
25	
26	        $rawBody = $request->getContent() ?: '';
27	        $signature = (string) $request->header('x-square-hmacsha256-signature', '');
28	
29	        if (! $this->isValidSignature($request, $rawBody, $signature)) {
30	            Log::warning('Square webhook rejected: invalid signature', [
31	                'ip' => $request->ip(),
32	                'event_type' => $request->input('type'),
33	            ]);
34	
35	            return $this->error('Invalid Square webhook signature.', 401);
36	        }
37	
38	        $payload = $request->json()->all();
39	        if (! is_array($payload)) {
40	            return $this->success(['received' => true, 'ignored' => 'invalid_payload']);
41	        }
42	
43	        $eventId = trim((string) ($payload['event_id'] ?? ''));
44	        if ($eventId !== '') {
45	            $dedupeKey = 'square:webhook:event:'.$eventId;
46	            if (! Cache::add($dedupeKey, true, now()->addHours(24))) {
47	                return $this->success(['received' => true, 'duplicate' => true]);
48	            }
49	        }
50	
51	        $eventType = trim((string) ($payload['type'] ?? ''));
52	        $merchantId = trim((string) ($payload['merchant_id'] ?? ''));
53	        if ($merchantId === '') {
54	            return $this->success(['received' => true, 'ignored' => 'missing_merchant_id']);
55	        }
56	
57	        if ($eventType === 'oauth.authorization.revoked') {
58	            ProfessionalIntegration::query()
59	                ->where('provider', ProfessionalIntegration::PROVIDER_SQUARE)
60	                ->where('external_account_id', $merchantId)
61	                ->delete();
62	
63	            return $this->success(['received' => true, 'revoked' => true]);
64	        }
65	
66	        if ($eventType !== 'catalog.version.updated') {
67	            return $this->success(['received' => true, 'ignored' => $eventType !== '' ? $eventType : 'unknown_event']);
68	        }
69	
70	        try {
71	            SyncSquareCatalogDeltaJob::dispatch($merchantId, null, false);
72	
73	            return $this->success(['received' => true, 'queued' => true]);
74	        } catch (\Throwable $dispatchError) {
75	            Log::warning('Square webhook queue dispatch failed; attempting inline sync', [
76	                'merchant_id' => $merchantId,
77	                'message' => $dispatchError->getMessage(),
78	            ]);
79	
80	            $integration = ProfessionalIntegration::query()
81	                ->where('provider', ProfessionalIntegration::PROVIDER_SQUARE)
82	                ->where('external_account_id', $merchantId)
83	                ->first();
84	
85	            $professional = $integration
86	                ? Professional::query()->find($integration->professional_id)
87	                : null;
88	
89	            if (! $professional) {
90	                return $this->success([
91	                    'received' => true,
92	                    'queued' => false,
93	                    'ignored' => 'merchant_not_found',
94	                ]);
95	            }
96	
97	            try {
98	                $stats = $syncService->syncFromSquare($professional, fullSync: false);
99	
100	                return $this->success([
101	                    'received' => true,
102	                    'queued' => false,
103	                    'synced_inline' => true,
104	                    'synced' => $stats['synced'] ?? 0,
105	                    'deleted' => $stats['deleted'] ?? 0,
106	                    'latest_time' => $stats['latest_time'] ?? null,
107	                ]);
108	            } catch (\Throwable $syncError) {
109	                Log::warning('Square webhook inline sync failed', [
110	                    'merchant_id' => $merchantId,
111	                    'message' => $syncError->getMessage(),
112	                ]);
113	
114	                // Return 200 to prevent noisy webhook retries; error is logged for investigation.
115	                return $this->success([
116	                    'received' => true,
117	                    'queued' => false,
118	                    'synced_inline' => false,
119	                ]);
120	            }
121	        }
122	    }
123	
124	    private function isValidSignature(Request $request, string $body, string $signature): bool
125	    {
126	        $key = trim((string) config('services.square.webhook_signature_key', ''));
127	        if ($key === '' || $signature === '') {
128	            return false;
129	        }
130	
131	        $configuredUrl = trim((string) config('services.square.webhook_notification_url', ''));
132	        $requestUrl = $request->fullUrl();
133	
134	        $candidateUrls = array_values(array_unique(array_filter([
135	            $configuredUrl !== '' ? $configuredUrl : null,
136	            $requestUrl,
137	            str_ends_with($requestUrl, '/catalog') ? substr($requestUrl, 0, -8) : null,
138	            str_ends_with($requestUrl, '/catalog') ? null : rtrim($requestUrl, '/').'/catalog',
139	            $configuredUrl !== '' && str_ends_with($configuredUrl, '/catalog') ? substr($configuredUrl, 0, -8) : null,
140	            $configuredUrl !== '' && ! str_ends_with($configuredUrl, '/catalog') ? rtrim($configuredUrl, '/').'/catalog' : null,
141	        ])));
142	
143	        foreach ($candidateUrls as $notificationUrl) {
144	            $expected = base64_encode(hash_hmac('sha256', $notificationUrl.$body, $key, true));
145	            if (hash_equals($expected, $signature)) {
146	                return true;
147	            }
148	        }
149	
150	        return false;
151	    }
152	}
